"use client";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { ToggleGroup as ToggleGroupPrimitive } from "@base-ui/react/toggle-group";
import { useRender } from "@base-ui/react/use-render";
import type { VariantProps } from "class-variance-authority";
import {
  type ComponentPropsWithRef,
  type CSSProperties,
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { cn } from "../lib/cn";
import { ControlSpan } from "../lib/control-animation";
import { useStateColor } from "../lib/css-motion";
import { bindMotionParameters, feedbackPress, stateIndicator } from "../lib/motion";
import { useMotionHostRef } from "../lib/motion-ref";
import { useCadenceMotion } from "../lib/provider";
import { toggleGroupColourReadable, toggleGroupColourScope } from "../lib/toggle-group-colour";
import { ToggleGroupSurface, useToggleGroupItem, useToggleGroupTransaction } from "../lib/toggle-group-motion";
import { useTextPresentation } from "../lib/use-text-presentation";
import { toggleVariants } from "../toggle";

type ToggleGroupVariant = "default" | "outline" | "segmented";
type ToggleGroupAppearance = Omit<VariantProps<typeof toggleVariants>, "variant"> & {
  variant?: ToggleGroupVariant | null;
};

const ToggleGroupContext = createContext<
  ToggleGroupAppearance & {
    spacing?: number;
    orientation?: "horizontal" | "vertical";
    multiple?: boolean;
  }
>({
  size: "default",
  variant: "default",
  spacing: 0,
  orientation: "horizontal",
});

export interface ToggleGroupProps extends ToggleGroupPrimitive.Props, ToggleGroupAppearance {
  spacing?: number;
  orientation?: "horizontal" | "vertical";
}
export interface ToggleGroupItemProps extends TogglePrimitive.Props, ToggleGroupAppearance {}

function ToggleGroup({
  className,
  variant,
  size,
  style,
  spacing = 0,
  orientation = "horizontal",
  multiple = false,
  children,
  render,
  ...props
}: ToggleGroupProps) {
  return (
    <ToggleGroupPrimitive
      render={(elementProps, state) => (
        <ToggleGroupSurface
          elementProps={elementProps}
          state={{ ...state, slot: "toggle-group" }}
          render={render}
          variant={variant ?? "default"}
          knownPaint={safePaint(className, style)}
        />
      )}
      data-variant={variant}
      data-size={size}
      data-spacing={spacing}
      orientation={orientation}
      data-orientation={orientation}
      multiple={multiple}
      data-multiple={multiple ? "" : undefined}
      style={(state) =>
        ({ "--gap": spacing, ...(typeof style === "function" ? style(state) : style) }) as CSSProperties
      }
      className={(state) =>
        cn(
          // Orientation is a JS branch, not a `data-vertical:` variant: Base UI writes
          // `data-orientation="vertical"`, while the shorthand utility compiles to
          // `[data-vertical]`, which nothing ever sets — a vertical group would lay out
          // as a row.
          "group/toggle-group relative isolate flex w-fit max-w-full gap-[calc(var(--spacing)*var(--gap))] rounded-lg p-1",
          orientation === "vertical" ? "flex-col items-stretch" : "items-center",
          variant === "segmented" ? "rounded-full bg-muted/60" : "border border-border/60 bg-muted/40",
          variant === "outline" && "bg-background shadow-xs",
          typeof className === "function" ? className(state) : className,
        )
      }
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size, spacing, orientation, multiple }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive>
  );
}

function ItemSurface({
  elementProps,
  state,
  render,
  variant,
  value,
  content,
  knownPaint,
}: {
  elementProps: ComponentPropsWithRef<"button">;
  state: TogglePrimitive.State;
  render: TogglePrimitive.Props["render"];
  variant: ToggleGroupAppearance["variant"];
  value: unknown;
  content: React.ReactNode;
  knownPaint: boolean;
}) {
  const { node, ref } = useMotionHostRef(elementProps.ref);
  const cm = useCadenceMotion(node);
  const context = useContext(ToggleGroupContext);
  const ItemPaint = useStateColor(
    ref,
    cm,
    [
      "background-color",
      "color",
      "border-top-color",
      "border-right-color",
      "border-bottom-color",
      "border-left-color",
      "box-shadow",
    ],
    {
      readability: knownPaint ? "verified" : "immediate",
      readabilityGate: toggleGroupColourReadable,
      readabilityScope: toggleGroupColourScope,
    },
  );
  useToggleGroupItem(node, value, state.pressed, [
    typeof content === "string" || typeof content === "number" ? content : null,
    elementProps.className,
    elementProps.style,
  ]);
  const [held, setHeld] = useState(false);
  const owner = useRef<number | string | null>(null);
  const staleActivation = useRef(false);
  const release = useCallback(() => {
    owner.current = null;
    setHeld(false);
  }, []);
  const disabled = state.disabled || elementProps["aria-disabled"] === true || elementProps["aria-disabled"] === "true";
  const plain = typeof content === "string" || typeof content === "number";
  const press = cm.parameters(bindMotionParameters(feedbackPress, "feedback.press/scale"));
  const safePress = plain && !render;
  useLayoutEffect(() => {
    if (disabled) {
      if (owner.current !== null) staleActivation.current = true;
      release();
    }
  }, [disabled, release]);
  useEffect(() => {
    if (!held) return;
    const end = (event: PointerEvent) => {
      if (event.pointerId === owner.current) release();
    };
    window.addEventListener("pointerup", end);
    window.addEventListener("pointercancel", end);
    return () => {
      window.removeEventListener("pointerup", end);
      window.removeEventListener("pointercancel", end);
    };
  }, [held, release]);
  const signature = useRef("");
  useLayoutEffect(() => {
    const host = node.current;
    if (!host) return;
    const reconcile = () => {
      const next = JSON.stringify([
        value,
        host.tagName,
        ...["type", "form", "formaction", "href"].map((name) => host.getAttribute(name)),
      ]);
      if (signature.current && signature.current !== next) {
        if (owner.current !== null) staleActivation.current = true;
        release();
      }
      signature.current = next;
    };
    reconcile();
    const observer = new MutationObserver(reconcile);
    observer.observe(host, { attributes: true, attributeFilter: ["type", "form", "formaction", "href"] });
    return () => observer.disconnect();
  });
  const children = !render && plain ? <GroupText value={String(content)} identity={value} /> : elementProps.children;
  return useRender({
    defaultTagName: "button",
    render,
    state: { ...state, slot: "toggle-group-item" },
    stateAttributesMapping: { pressed: () => null, disabled: () => null },
    props: {
      ...elementProps,
      ...ItemPaint,
      "data-slot": "toggle-group-item",
      style: { ...ItemPaint.style, ...elementProps.style },
      ref: ItemPaint.ref,
      "data-motion": cm.mode,
      onPointerDown(event: React.PointerEvent<HTMLButtonElement>) {
        elementProps.onPointerDown?.(event);
        if (!disabled && event.button === 0 && event.isPrimary && owner.current === null) {
          staleActivation.current = false;
          owner.current = event.pointerId;
          setHeld(true);
        }
      },
      onPointerUp(event: React.PointerEvent<HTMLButtonElement>) {
        elementProps.onPointerUp?.(event);
        if (owner.current === event.pointerId) release();
      },
      onPointerCancel(event: React.PointerEvent<HTMLButtonElement>) {
        elementProps.onPointerCancel?.(event);
        if (owner.current === event.pointerId) release();
      },
      onLostPointerCapture(event: React.PointerEvent<HTMLButtonElement>) {
        elementProps.onLostPointerCapture?.(event);
        if (owner.current === event.pointerId) release();
      },
      onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
        elementProps.onKeyDown?.(event);
        if (
          !disabled &&
          (event.key === "Enter" || event.key === " ") &&
          event.target === event.currentTarget &&
          owner.current === null
        ) {
          staleActivation.current = false;
          owner.current = event.key;
          setHeld(true);
        }
      },
      onKeyUp(event: React.KeyboardEvent<HTMLButtonElement>) {
        elementProps.onKeyUp?.(event);
        if (owner.current === event.key) release();
      },
      onBlur(event: React.FocusEvent<HTMLButtonElement>) {
        elementProps.onBlur?.(event);
        release();
      },
      onClick(event: React.MouseEvent<HTMLButtonElement>) {
        if (staleActivation.current) {
          event.preventDefault();
          return;
        }
        elementProps.onClick?.(event);
      },
      children: (
        <>
          {context.multiple ? (
            <LocalIndicator selected={state.pressed} variant={variant} knownPaint={knownPaint} />
          ) : (
            state.pressed && (
              <span
                aria-hidden="true"
                data-slot="toggle-group-fallback"
                data-motion={cm.mode}
                className={cn(
                  "pointer-events-none absolute inset-0 -z-10 rounded-[inherit] bg-accent group-data-[marker-ready]/toggle-group:hidden",
                  variant === "segmented" && "bg-background shadow-sm dark:bg-input",
                )}
              />
            )
          )}
          {safePress && press.kind === "press" ? (
            <ControlSpan
              data-slot="toggle-group-content"
              data-motion={cm.mode}
              className="relative z-10 inline-flex items-center justify-center gap-[inherit]"
              target={{ scale: cm.reduced || disabled ? 1 : held ? press.scale : 1 }}
              transition={press.transition}
            >
              {children}
            </ControlSpan>
          ) : (
            children
          )}
        </>
      ),
    },
  });
}
function LocalIndicator({
  selected,
  variant,
  knownPaint,
}: {
  selected: boolean;
  variant: ToggleGroupAppearance["variant"];
  knownPaint: boolean;
}) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const LocalPaint = useStateColor(ref, cm, ["background-color", "box-shadow"], {
    readability: knownPaint ? "verified" : "immediate",
    readabilityGate: toggleGroupColourReadable,
    readabilityScope: toggleGroupColourScope,
  });
  const parameters = cm.parameters(bindMotionParameters(stateIndicator, "state.morph/indicator"));
  if (parameters.kind !== "indicator") return null;
  return (
    <ControlSpan
      {...LocalPaint}
      aria-hidden="true"
      data-slot="toggle-group-local-indicator"
      data-motion={cm.mode}
      className={cn(
        "pointer-events-none absolute inset-0 -z-10 rounded-[inherit] bg-accent",
        variant === "segmented" && "bg-background shadow-sm dark:bg-input",
      )}
      target={{ opacity: selected ? 1 : 0, scale: cm.reduced || selected ? 1 : parameters.scale }}
      transition={{ opacity: parameters.opacity, scale: parameters.spatial }}
    />
  );
}
function GroupText({ value, identity }: { value: string; identity: unknown }) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const entity = useRef({ identity, token: {} });
  if (!Object.is(identity, entity.current.identity)) entity.current = { identity, token: {} };
  const transaction = useToggleGroupTransaction();
  const text = useTextPresentation(
    node,
    value,
    cm,
    entity.current.token,
    { characterStagger: false, stripGeometry: true },
    transaction,
  );
  return (
    <span ref={ref} data-slot="toggle-group-text" data-motion={cm.mode}>
      {text}
    </span>
  );
}
function ToggleGroupItem({ className, children, variant, size, render, ...props }: ToggleGroupItemProps) {
  const cm = useCadenceMotion();
  const context = useContext(ToggleGroupContext);
  const resolvedVariant = context.variant ?? variant;
  const resolvedSize = context.size ?? size;
  // Neighbor joins follow the group's axis and use logical inline corners for RTL.
  const vertical = context.orientation === "vertical";
  const joined = context.spacing === 0;

  return (
    <TogglePrimitive
      data-variant={resolvedVariant}
      data-size={resolvedSize}
      data-spacing={context.spacing}
      data-motion={cm.mode}
      className={(state) =>
        cn(
          toggleVariants({ size: resolvedSize }),
          "relative w-auto min-w-0 shrink-0 rounded-md px-3 text-muted-foreground hover:bg-transparent hover:text-foreground data-pressed:bg-transparent data-pressed:text-foreground",
          resolvedVariant === "segmented" && "rounded-full",
          joined &&
            context.multiple &&
            (vertical
              ? "data-pressed:[&:has(+[data-pressed])]:rounded-b-none [&[data-pressed]+[data-pressed]]:rounded-t-none"
              : "data-pressed:[&:has(+[data-pressed])]:rounded-e-none [&[data-pressed]+[data-pressed]]:rounded-s-none"),
          typeof className === "function" ? className(state) : className,
        )
      }
      render={(elementProps, state) => (
        <ItemSurface
          elementProps={elementProps}
          state={state}
          render={render}
          variant={resolvedVariant}
          value={props.value}
          content={children}
          knownPaint={safePaint(className, props.style)}
        />
      )}
      {...props}
    >
      {children}
    </TogglePrimitive>
  );
}

export { ToggleGroup, ToggleGroupItem };

function safePaint(className: unknown, style: unknown) {
  return (
    typeof className !== "function" &&
    typeof style !== "function" &&
    !Object.keys((style ?? {}) as object).some((key) =>
      /color|background|shadow|opacity|filter|blend|^--(?!motion-|cadence-|ease-)/i.test(key),
    ) &&
    (typeof className !== "string" ||
      className
        .split(/\s+/)
        .every((name) =>
          /^(?:[\w-]+:)*(?:w-|h-|size-|min-|max-|p[xytrblse]?-|m[xytrblse]?-|gap-|flex|inline-|block|grid|shrink|grow|basis-|items-|justify-|self-|order-|relative|overflow-)/.test(
            name,
          ),
        ))
  );
}

"use client";

import { bindMotionParameters, motionMilliseconds, presenceInline } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import { createMotionTransaction, type MotionLease } from "./motion-transaction";
import type { CadenceMotion } from "./provider";

export type InlinePresenceCommit = {
  present: boolean;
  enter: boolean;
  cm: CadenceMotion;
};

/** Entrance opacity only, on the original group host. Never writes a resting opacity. */
export function createInlineEntrance(node: HTMLElement) {
  const transaction = createMotionTransaction();
  const owner = transaction.register(node);
  let current: InlinePresenceCommit | null = null;
  let lease: MotionLease | null = null;
  let animation: Animation | null = null;
  let alive = true;
  let blocked = false;
  let generation = 0;
  let signature = "";
  const cancel = () => {
    generation++;
    animation?.cancel();
    animation = null;
    lease?.cancel();
    lease = null;
  };
  const settle = () => {
    cancel();
  };
  const callerOpacity = (css = node.ownerDocument.defaultView?.getComputedStyle(node)) => {
    if (!css) return false;
    const family = css.transitionProperty.split(",").map((property) => property.trim());
    const times = css.transitionDuration.split(",").map((time) => Number.parseFloat(time));
    return (
      family.some(
        (property, index) => ["all", "opacity"].includes(property) && (times[index % times.length] ?? 0) > 0,
      ) ||
      (node.getAnimations?.() ?? []).some(
        (handle) =>
          handle !== animation &&
          (handle.effect as KeyframeEffect | null)?.getKeyframes().some((frame) => "opacity" in frame),
      )
    );
  };
  const play = (from?: string, forceImmediate = false) => {
    const input = current;
    if (!alive || !input) return;
    if (!input.present) {
      settle();
      return;
    }
    const parameters = input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
    if (parameters.kind !== "visual") return;
    const clock = parameters.opacity;
    const immediate = forceImmediate || blocked || clock.duration === 0;
    if (
      (immediate && input.present) ||
      !node.isConnected ||
      typeof node.animate !== "function" ||
      (input.present && node.contains(node.ownerDocument.activeElement))
    ) {
      settle();
      return;
    }
    const css = node.ownerDocument.defaultView?.getComputedStyle(node);
    if (!css || css.display === "none" || css.visibility === "hidden") {
      settle();
      return;
    }
    if (callerOpacity(css)) {
      settle();
      return;
    }
    const epoch = ++generation;
    const revision = transaction.revision("presence", input.present, node);
    let handle: Animation | null = null;
    lease = owner.begin(revision, ["opacity"], {}, () => handle?.cancel());
    if (!lease?.current()) return;
    const owned = lease;
    handle = node.animate([{ opacity: from ?? 0 }, { opacity: css.opacity }], {
      duration: motionMilliseconds(immediate ? 0 : Number(clock.duration)),
      delay: motionMilliseconds(immediate ? 0 : Number(clock.delay ?? 0)),
      easing: `cubic-bezier(${input.cm.scope.tokens.ease.out.join(",")})`,
      fill: "both",
    });
    animation = handle;
    void handle.finished.then(
      () => {
        if (
          !alive ||
          !node.isConnected ||
          epoch !== generation ||
          !owned.current() ||
          current?.present !== input.present
        )
          return;
        settle();
      },
      () => {},
    );
    if (immediate) handle.finish();
  };
  const interact = () => {
    if (current?.present) settle();
  };
  for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
    node.addEventListener(event, interact, true);
  const opacityStyle = () => {
    const style = node.style;
    return JSON.stringify([
      style.opacity,
      style.animation,
      /(?:^|,)\s*(?:all|opacity)\s*(?:,|$)/.test(style.transitionProperty) ? style.transition : "",
      Array.from(style)
        .filter((name) => name.startsWith("--") && !/^--(?:cadence-|motion-|ease-cadence)/.test(name))
        .map((name) => [name, style.getPropertyValue(name)]),
    ]);
  };
  let callerStyle = opacityStyle();
  const observer = new MutationObserver((records) => {
    const next = opacityStyle();
    // Scoped colour clocks and inherited Cadence tokens are another owned
    // family. Only potentially conflicting caller paint revokes this channel.
    if (
      (next !== callerStyle || records.some((record) => record.attributeName !== "style")) &&
      (current?.present || callerOpacity())
    )
      settle();
    callerStyle = next;
  });
  observer.observe(node, { attributes: true, attributeFilter: ["class", "style", "disabled", "aria-disabled"] });
  const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (environment) => {
    blocked = environment.hidden || environment.immediate;
    if (blocked || (environment.reduced && animation && current?.cm.mode === "full")) {
      settle();
    }
  });
  return {
    commit(input: InlinePresenceCommit) {
      const previous = current;
      current = input;
      // Resolve the exact entrance clock on every committed policy, including native baselines.
      const parameters = input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
      const clock = JSON.stringify(parameters);
      const retime = signature !== clock;
      signature = clock;
      const change = previous ? previous.present !== input.present : input.enter || !input.present;
      if (change) {
        const from = animation ? node.ownerDocument.defaultView?.getComputedStyle(node).opacity : undefined;
        cancel();
        play(from);
      } else if (input.cm.disabled || input.cm.timeScale === 0) {
        settle();
      } else if (retime && animation) {
        const from = node.ownerDocument.defaultView?.getComputedStyle(node).opacity;
        cancel();
        play(from);
      }
    },
    dispose() {
      alive = false;
      cancel();
      owner.dispose();
      observer.disconnect();
      unsubscribe();
      for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
        node.removeEventListener(event, interact, true);
    },
  };
}

"use client";

import { naturalGeometry } from "./measured-geometry";
import { motionLimits } from "./motion";
import type { SelectionBox } from "./selection-projection";
import type { TabsStripSnapshot } from "./tabs-layout";

/** Derive the actual CSS scale; offsetWidth is integer-rounded and must not
 * invent a fractional scale on an ordinary untransformed strip. */
export function selectionScale(element: HTMLElement) {
  let x = 1,
    y = 1,
    current: HTMLElement | null = element;
  for (let depth = 0; current && depth < 32; depth++, current = current.parentElement) {
    const css = getComputedStyle(current);
    const matrix = css.transform === "none" ? null : new DOMMatrixReadOnly(css.transform);
    if (
      css.rotate !== "none" ||
      css.perspective !== "none" ||
      css.offsetPath !== "none" ||
      (matrix && (!matrix.is2D || matrix.b !== 0 || matrix.c !== 0 || matrix.a <= 0 || matrix.d <= 0))
    )
      return null;
    const scale = css.scale === "none" ? [1, 1] : css.scale.split(/\s+/).map(Number);
    const zoom = css.zoom === "normal" ? 1 : Number(css.zoom);
    const sx = (scale[0] ?? 1) * (matrix?.a ?? 1) * zoom,
      sy = (scale[1] ?? scale[0] ?? 1) * (matrix?.d ?? 1) * zoom;
    if (!Number.isFinite(sx) || !Number.isFinite(sy) || sx <= 0 || sy <= 0) return null;
    x *= sx;
    y *= sy;
  }
  return current || !Number.isFinite(x) || !Number.isFinite(y) ? null : { x, y };
}

export function selectionStripSnapshot(
  list: HTMLElement,
  strip: HTMLElement,
  records: { host: HTMLElement; active: boolean }[],
  marker: SelectionBox | null,
  orientation: string,
): TabsStripSnapshot | null {
  if (
    records.length > motionLimits.collectionVisuals ||
    !list.getClientRects().length ||
    !strip.getClientRects().length
  )
    return null;
  const css = getComputedStyle(list),
    bounds = list.getBoundingClientRect();
  const axis = orientation === "vertical" ? "height" : "width";
  const intrinsic = list.computedStyleMap?.().get(axis)?.toString();
  if (
    !intrinsic ||
    !["auto", "fit-content", "max-content"].includes(intrinsic) ||
    css.writingMode !== "horizontal-tb" ||
    css.aspectRatio !== "auto"
  )
    return null;
  const native = naturalGeometry(list);
  if (!native) return null;
  const properties = css.transitionProperty.split(",").map((value) => value.trim());
  const durations = css.transitionDuration.split(",").map(Number.parseFloat);
  if (
    properties.some(
      (property, index) =>
        ["all", "width", "height", "transform", "translate", "scale", "rotate"].includes(property) &&
        (durations[index % durations.length] ?? 0) > 0,
    ) ||
    list
      .getAnimations()
      .some((a) =>
        (a.effect as KeyframeEffect | null)
          ?.getKeyframes()
          .some((frame) => ["width", "height", "transform", "translate", "scale", "rotate"].some((p) => p in frame)),
      )
  )
    return null;
  const scale = selectionScale(list);
  const sx = scale?.x ?? 0,
    sy = scale?.y ?? 0;
  if (!(sx > 0 && sy > 0)) return null;
  const items = new Map<HTMLElement, SelectionBox>();
  for (const { host } of records) {
    if (host.parentElement !== strip || !host.getClientRects().length) return null;
    const paint = getComputedStyle(host);
    if (
      [paint, css].some(
        (s) =>
          s.transform !== "none" ||
          s.translate !== "none" ||
          s.scale !== "none" ||
          s.rotate !== "none" ||
          /fixed|sticky/.test(s.position),
      )
    )
      return null;
    if (
      host
        .getAnimations()
        .some((a) =>
          (a.effect as KeyframeEffect | null)
            ?.getKeyframes()
            .some((f) => ["transform", "translate", "scale", "rotate"].some((p) => p in f)),
        )
    )
      return null;
    const rect = host.getBoundingClientRect();
    items.set(host, {
      x: (rect.left - bounds.left) / sx + list.scrollLeft - list.clientLeft,
      y: (rect.top - bounds.top) / sy + list.scrollTop - list.clientTop,
      width: rect.width / sx,
      height: rect.height / sy,
    });
  }
  return {
    axis,
    size: native[axis],
    items,
    marker,
    strip,
    inlineSize: strip.getBoundingClientRect().width / sx,
    blockSize: strip.getBoundingClientRect().height / sy,
    selected: records.find((record) => record.active)?.host,
    crossWidth:
      orientation === "vertical" &&
      ["auto", "fit-content", "max-content"].includes(list.computedStyleMap?.().get("width")?.toString() ?? "")
        ? native.width
        : undefined,
    crossHeight:
      orientation !== "vertical" &&
      ["auto", "fit-content", "max-content"].includes(list.computedStyleMap?.().get("height")?.toString() ?? "")
        ? native.height
        : undefined,
    clipped: (axis === "width" ? css.overflowX : css.overflowY) !== "visible",
    crossClipped: (axis === "width" ? css.overflowY : css.overflowX) !== "visible",
  };
}

"use client";

